"""Contact UI from the user reference, with an honest frontend-only enquiry flow."""
def contact_field(key,title,typ,icon,placeholder,required=False,autocomplete='off'):
 return f'<div class="contact-field"><label for="contact-{key}">{title}{" <span>*</span>" if required else ""}</label><div class="contact-input"><i data-lucide="{icon}" aria-hidden="true"></i><input id="contact-{key}" name="{key}" type="{typ}" placeholder="{placeholder}" {"required" if required else ""} autocomplete="{autocomplete}" aria-describedby="contact-{key}-error"></div><span class="contact-error" id="contact-{key}-error"></span></div>'
contact=f'''<section class="capabilities-hero contact-hero"><div class="capabilities-hero-photo">{img(1589,'Company building and landscaped walkway at Techno Printpack',eager=True)}</div><div class="capabilities-hero-angle"></div><div class="container"><div>{label('CONTACT US')}<h1>Get in Touch<br>with <span>Techno Printpack</span></h1><p>Have a query, a custom packaging requirement or a project in mind? Talk to our team.</p><div class="capabilities-breadcrumb" aria-label="Breadcrumb"><a href="index.html"><i data-lucide="house" aria-hidden="true"></i>Home</a><span aria-hidden="true">›</span><span>Contact</span></div></div></div></section>
<section class="contact-reference-body"><div class="container"><div class="contact-main-layout"><div class="contact-information"><h2>Contact Information</h2><span class="contact-accent"></span><p>Reach out for product enquiries, quotations, partnerships or general information.</p><div class="contact-info-row"><i data-lucide="phone" aria-hidden="true"></i><div><h3>Phone</h3><a href="tel:+94382257170">+94 38 225 7170</a><a class="contact-secondary" href="tel:+94777777648">Mobile: +94 777 777 648</a></div></div><div class="contact-info-row"><i data-lucide="mail" aria-hidden="true"></i><div><h3>Email</h3><a href="mailto:info@technoind.biz">info@technoind.biz</a></div></div><div class="contact-info-row"><i data-lucide="map-pin" aria-hidden="true"></i><div><h3>Address</h3><p>227/1, Ghanarathana Mw,<br>Raigama, Bandaragama,<br>Sri Lanka.</p></div></div><div class="contact-info-row"><i data-lucide="clock-3" aria-hidden="true"></i><div><h3>Visiting Us</h3><p>Please call to arrange your visit.</p><p class="contact-secondary">Business hours are awaiting confirmation.</p></div></div></div>
<div class="contact-message-panel"><h2>Send Us a Message</h2><span class="contact-accent"></span><p>Build your enquiry below, then review and send it using your email app.</p><form id="contact-form" novalidate><div class="contact-form-grid">{contact_field('name','Full Name','text','user-round','Enter your name',True,'name')}{contact_field('company','Company / Organization','text','building-2','Enter company name',False,'organization')}{contact_field('email','Email Address','email','mail','Enter your email',True,'email')}{contact_field('phone','Contact Number','tel','phone','Enter your phone number',True,'tel')}<div class="contact-field full"><label for="contact-subject">Subject <span>*</span></label><div class="contact-input"><i data-lucide="tag" aria-hidden="true"></i><select id="contact-subject" name="subject" required aria-describedby="contact-subject-error"><option>Product Enquiry</option><option>Quotation Request</option><option>Quality & Documentation</option><option>Partnership Enquiry</option><option>General Information</option></select></div><span class="contact-error" id="contact-subject-error"></span></div><div class="contact-field full"><label for="contact-message">Message <span>*</span></label><div class="contact-input message-input"><i data-lucide="message-circle" aria-hidden="true"></i><textarea id="contact-message" name="message" rows="4" placeholder="Tell us how we can help…" required aria-describedby="contact-message-error"></textarea></div><span class="contact-error" id="contact-message-error"></span></div></div><div class="contact-form-actions"><button class="button" type="submit"><i data-lucide="send" aria-hidden="true"></i>Prepare Message</button><button class="contact-whatsapp" id="contact-whatsapp" type="button" disabled><i data-lucide="message-circle" aria-hidden="true"></i>Chat on WhatsApp</button></div><p class="contact-form-note" id="contact-whatsapp-note">Official WhatsApp availability is awaiting confirmation.</p><p class="contact-form-note">This form does not submit or store information. Nothing is sent until you send it in your email or messaging app.</p><p class="contact-form-status" id="contact-status" role="status"></p><section id="contact-preview" hidden aria-label="Review your contact enquiry"><h3>Review your message</h3><pre id="contact-message-preview"></pre><div class="button-row"><a class="button" id="contact-email-draft" href="mailto:info@technoind.biz">Open Email Draft <span aria-hidden="true">↗</span></a><button type="button" class="text-link" id="contact-copy">Copy message</button></div><p class="contact-form-note">Opening your email app does not send the message. Review it and press Send there.</p></section></form></div></div>
<div class="contact-lower-layout"><section class="contact-location" id="location" aria-label="Company location"><iframe title="Google Maps search for Techno Print Pack, Raigama, Bandaragama" src="https://maps.google.com/maps?q=Techno%20Print%20Pack%20Raigama%20Bandaragama&amp;output=embed" width="600" height="280" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a href="https://www.google.com/maps/search/?api=1&query=Techno+Print+Pack+Raigama+Bandaragama" target="_blank" rel="noopener">Open directions in Google Maps <span aria-hidden="true">↗</span></a><p>Map search uses the published company name and address. Confirm the exact directions with our team.</p></section><section class="contact-quote-banner"><div class="contact-quote-photo">{img(1529,'Corrugated packaging materials inside the company factory')}</div><i data-lucide="package" aria-hidden="true"></i><div><h2>Need a Custom Packaging Solution?</h2><p>Let’s discuss your requirements and the right packaging for your business.</p>{btn('Request a Quote','quotation.html')}</div></section></div></div></section>'''
contact=contact.replace('<form id="contact-form"','<noscript><p>Please <a class="text-link" href="mailto:info@technoind.biz">email info@technoind.biz</a> or call the team using the contact details on this page.</p></noscript><form id="contact-form"')
contact=contact.replace('<iframe title="Google Maps','<div class="contact-map-embed"><iframe title="Google Maps').replace('</iframe><a href="https://www.google.com/maps','</iframe><div class="contact-map-label"><i data-lucide="map-pin" aria-hidden="true"></i><span><strong>Techno Printpack</strong><span>Raigama · Bandaragama</span></span></div></div><a href="https://www.google.com/maps')
pages['contact']=('Contact Us','Contact Techno Printpack in Raigama, Bandaragama for packaging enquiries, quotation discussions and company information.',contact)
